| --td-toast-color | @text-color-anti | - |
| --td-toast-column-icon-size | 64rpx | - |
| --td-toast-max-width | 370rpx | - |
| --td-toast-radius | @radius-default | - |
| --td-toast-row-icon-size | 48rpx | - |
